449	func TestAmountOverflowOnSetKeepsOldSetting(t *testing.T) {
450		// 未开日、未设金额上限时报价可使持仓市值溢出：低位建仓后报价涨到天价。
451		e, _ := NewEngine(1_000_000)
452		mustSetMax(t, e, "A", 10)
453		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
454		id := mustBuy(t, e, "A", 3, 10)
455		if _, err := e.Fill(Trade{TradeID: 1, OrderID: id, Symbol: "A", Side: Buy, Price: 10, Qty: 3}); err != nil {
456			t.Fatal(err)
457		}
458		mustQuote(t, e, "A", Quote{Seq: 2, Moment: 2, Price: math.MaxInt64}, 1) // 3×MaxInt64 溢出
459	
460		// 当前合计已溢出：任何设置都整体报错，只增加一条拒绝记录且不进入启用态。
461		before := len(e.Records())
462		_, err := e.SetPositionAmountLimit(math.MaxInt64)
463		if !errors.Is(err, ErrInt64Overflow) {
464			t.Fatalf("设置时金额溢出必须返回 ErrInt64Overflow，实际 %v", err)
465		}
466		if st := e.PositionAmountStatus(); st.Enabled {
467			t.Fatal("溢出后设置不得生效")
468		}
469		if len(e.Records()) != before+1 || e.Records()[before].Kind != RecordRejected {
470			t.Fatal("溢出设置只能增加一条拒绝记录")
471		}
472	
473		// 负值报错且保留原设置（此时仍是未启用）。
474		if _, err := e.SetPositionAmountLimit(-1); err == nil {
475			t.Fatal("负上限必须报错")
476		}
477	
478		// 合法设置后再下单致申请后合计溢出：下单整体报错并留一条拒绝，上限保持不变。
479		e2, _ := NewEngine(math.MaxInt64)
480		mustSetMax(t, e2, "A", 10)
481		mustQuote(t, e2, "A", Quote{Seq: 1, Moment: 1, Price: 5}, 1)
482		bid := mustBuy(t, e2, "A", 1, 5)
483		if _, err := e2.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "A", Side: Buy, Price: 5, Qty: 1}); err != nil {
484			t.Fatal(err)
485		}
486		mustQuote(t, e2, "A", Quote{Seq: 2, Moment: 2, Price: math.MaxInt64}, 1) // 持仓 1×MaxInt64
487		if _, err := e2.SetPositionAmountLimit(math.MaxInt64); err != nil {
488			t.Fatalf("合计恰为 MaxInt64 时设置应成功: %v", err)
489		}
490		before = len(e2.Records())
491		// 限价 5 通过现金检查；占用按 max(限价 5, 报价 MaxInt64) 计，与持仓合计溢出。
492		if _, err := e2.Buy("A", 1, 5); !errors.Is(err, ErrInt64Overflow) {
493			t.Fatalf("申请后合计溢出必须返回 ErrInt64Overflow，实际 %v", err)
494		}
495		if len(e2.Records()) != before+1 || e2.Records()[before].Kind != RecordRejected {
496			t.Fatal("溢出下单只能增加一条拒绝记录")
497		}
498		if st := e2.PositionAmountStatus(); !st.Enabled || st.Limit != math.MaxInt64 {
499			t.Fatalf("溢出下单不得改写上限: %+v", st)
500		}
501	}
