503	func TestAmountOverflowQuoteBatchRollsBack(t *testing.T) {
504		e, _ := NewEngine(1_000_000)
505		mustSetMax(t, e, "A", 10)
506		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 1, Price: 10}, 1)
507		id := mustBuy(t, e, "A", 5, 10) // 占用 50
508		if _, err := e.SetPositionAmountLimit(1_000_000); err != nil {
509			t.Fatal(err)
510		}
511	
512		// seq3 溢出报价先等待；补齐 seq2 时链中 seq3 使 5×MaxInt64 溢出，整批回滚。
513		mustQuote(t, e, "A", Quote{Seq: 3, Moment: 3, Price: math.MaxInt64}, 0)
514		before := len(e.Records())
515		n, err := e.UpdateQuote("A", Quote{Seq: 2, Moment: 2, Price: 11})
