596		if _, err := e.Fill(tr); err != nil {
597			t.Fatal(err)
598		}
599		before := e.PositionAmountStatus()
600		recs = len(e.Records())
601		if _, err := e.Fill(tr); err != nil {
602			t.Fatal(err)
603		}
604		after := e.PositionAmountStatus()
605		if before != after || len(e.Records()) != recs {
606			t.Fatalf("成交重放不得改变金额状态或新增记录: before=%+v after=%+v", before, after)
607		}
