609	
610	func TestAmountRejectQuoteRefsIncludeApplyingSymbol(t *testing.T) {
611		// 只有 B 持仓占用额度；A 本身无持仓无买单，但其报价决定本次买单占用单价。
612		e, _ := NewEngine(1_000_000)
613		mustSetMax(t, e, "A", 1_000)
614		mustSetMax(t, e, "B", 1_000)
615		mustQuote(t, e, "A", Quote{Seq: 1, Moment: 70, Price: 10}, 1)
616		mustQuote(t, e, "B", Quote{Seq: 1, Moment: 1, Price: 20}, 1)
617		bid := mustBuy(t, e, "B", 5, 20) // 占用 100，达成持仓前置
618		if _, err := e.Fill(Trade{TradeID: 1, OrderID: bid, Symbol: "B", Side: Buy, Price: 20, Qty: 5}); err != nil {
619			t.Fatal(err)
620		}
621		if _, err := e.SetPositionAmountLimit(150); err != nil {
622			t.Fatal(err)
623		}
624		// B 持仓 100；A 买单 6 股限价 5，按报价 10 占用 60，申请后 160 > 150。
625		if _, err := e.Buy("A", 6, 5); err == nil {
626			t.Fatal("必须拒绝")
627		}
628		rec := lastAmountRecord(t, e, RecordRejected)
629		if rec.AmtApplyTotal != 160 || rec.AmtTotal != 100 {
630			t.Fatalf("拒绝快照金额错误: %+v", rec)
631		}
632		var hasA, hasB bool
633		for _, rf := range rec.AmtQuoteRefs {
634			if rf.Symbol == "A" && rf.Seq == 1 && rf.Moment == 70 && rf.Price == 10 {
635				hasA = true
636			}
637			if rf.Symbol == "B" && rf.Seq == 1 && rf.Price == 20 {
638				hasB = true
639			}
640		}
641		if !hasA || !hasB || len(rec.AmtQuoteRefs) != 2 {
642			t.Fatalf("报价定位必须包含申请合约 A 与持仓合约 B: %+v", rec.AmtQuoteRefs)
643		}
644	}
