646	func lastAmountRecord(t *testing.T, e *Engine, kind RecordKind) Record {
647		t.Helper()
648		for i := len(e.records) - 1; i >= 0; i-- {
649			if e.records[i].Kind == kind && e.records[i].AmtEnabled {
650				return e.records[i]
651			}
652		}
653		t.Fatal("不存在携带金额快照的记录")
654		return Record{}
655	}
